#!/usr/bin/env python3 -I
# Implements prompts/PDF2BIM_VECTOR_PROBE.md §43.21 step 2 — writes migration CL011: door families at the DIN 18101 opening sizes a German
# Werkplan scan needs (raster_doors.py doors.json). Mesh shape as gen_door_families.py (§38). Deterministic: same inputs -> same bytes. Witness: W-S21f.
# Usage: gen_werkplan_door_families.py <doors.json>[:<height mm>][,...] <german_werkplan_efh.json> [<earlier CLnnn.sql>,... [<label, default CL011>]] > migration/CLnnn_....sql
#   §43.21 step 3: a doors.json may carry its storey's measured door height (section_heights.json doors[].model_mm); none = the DEFAULT door_height()
import sys, json, os
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from family_mesh import TRI, box, along_y, blob
def door_height(T): return T['door_series']['height_mm']['opening_page_nennmass']   # §43.21 step 2 DEFAULT: the DIN 18101 opening Nennmaß
def fid_of(w, d, H): return 'DEWP_D%d%s_%dx%d' % (w, '' if d == 365 else 'd%d' % d, w, H)   # one owner of the id: raster_emit.py imports it

def mesh(w, h, d, F, L):
    "centred, X width, Y depth, Z height: the size is the opening (DIN Nennmaß). Head and 2 jambs, the shut leaf between the jambs down to the floor (§38 shape)"
    hw, hh, hd = w / 2, h / 2, d / 2
    b = [box(-hw, hw, -hd, hd, hh - F, hh), box(-hw, -hw + F, -hd, hd, -hh, hh - F), box(hw - F, hw, -hd, hd, -hh, hh - F), box(-hw + F, hw - F, -L / 2, L / 2, -hh, hh - F)]
    V = []; I = []
    for q in b:
        o = len(V); V += q; I += [(a + o, c + o, e + o) for a, c, e in TRI]
    return V, I

if __name__ == '__main__':
    T = json.load(open(sys.argv[2])); DS = T['door_system']
    H0 = door_height(T); F = DS['frame_face_mm'] / 1000; L = DS['leaf_mm'] / 1000
    DOORS = [(d, int(p.split(':')[1]) if ':' in p else H0) for p in sys.argv[1].split(',') for d in json.load(open(p.split(':')[0]))['doors']]
    LABEL = sys.argv[4] if len(sys.argv) > 4 else 'CL011'
    PRIOR = ''.join(open(f).read() for f in sys.argv[3].split(',')) if len(sys.argv) > 3 else ''
    sizes = sorted({(d['nominal_mm'], round(d['thk_m'] * 1000), h) for d, h in DOORS})
    skipped = [fid_of(w, d, H) for w, d, H in sizes if "'%s'" % fid_of(w, d, H) in PRIOR]; sizes = [(w, d, H) for w, d, H in sizes if "'%s'" % fid_of(w, d, H) not in PRIOR]
    measured = any(H != H0 for w, d, H in sizes)
    hl = ("Height: per storey, the section's measured floor build-up + the DIN 18101 class (§43.21 step 3)." if measured else
          "Height: %d, the opening Nennmaß (DEFAULT until §43.21 step 3)." % H0)
    print("-- " + LABEL + ": door families at the DIN 18101 opening sizes a German Werkplan scan needs, generated by scripts/pdf2bim/gen_werkplan_door_families.py. DO NOT hand-edit: regenerate.\n"
          "-- Spec: prompts/PDF2BIM_VECTOR_PROBE.md §43.21 step " + ('3' if measured else '2') + ". Width: DIN 18101 Nennmaß (door_series). " + hl + " Depth: the wall's READ thickness. Frame face, leaf: template defaults, YELLOW.\n"
          "-- Data only, append-only, idempotent: INSERT OR IGNORE. Applies to library/component_library.db (never commit the binary: this script is the change)."
          + ("\n-- Sizes already in an earlier migration, not repeated: %s" % skipped if skipped else "") + "\nBEGIN TRANSACTION;")
    for w, d, H in sizes:
        fid = fid_of(w, d, H); lab = fid.split('_')[1]
        desc = '%s %d×%dmm DIN 18101 opening%s, single leaf, depth %d mm. Generated (German Werkplan type); frame and leaf are defaults.' % (lab, w, H, '' if H == H0 else ' (height over the raw slab: measured floor build-up + DIN class)', d)
        print("INSERT OR IGNORE INTO ad_opening_family (family_id,family_name,opening_type,ifc_class,default_width_mm,default_height_mm,is_fire_rated,description,is_active,depth_mm) VALUES ('%s','DE Werkplan door %dx%dmm','DOOR','IfcDoor',%d,%d,0,'%s',1,%d);" % (fid, w, H, w, H, desc.replace("'", "''"), d))
        V, I = mesh(w / 1000, H / 1000, d / 1000, F, L); ref = '%s: %d x %d generated' % (lab, w, H); o = w * 100000 + H * 10 + d   # an ordinal no committed row uses (§39)
        for VV in (V, along_y(V)):
            v, f, hh = blob(VV, I); o += 1
            print("INSERT OR IGNORE INTO component_geometries (geometry_hash,vertices,faces,normals,vertex_count,face_count) VALUES ('%s',x'%s',x'%s',NULL,%d,%d);" % (hh, v.hex(), f.hex(), len(VV), len(I)))
            print("INSERT OR IGNORE INTO ad_geometry_map (building_type,element_ref,ifc_class,storey,ordinal,geometry_hash,source,provenance) VALUES ('German Werkplan EFH','%s','IfcDoor','Generated',%d,'%s','DIN 18101 + template, gen_werkplan_door_families.py','PARAMETRIC');" % (ref, o, hh))
    print('COMMIT;')
